<?php
namespace App\Services;
use App\Models\Central\PlatformAuditLog;use App\Models\User;use Illuminate\Database\Eloquent\Model;use Illuminate\Http\Request;use Illuminate\Support\Arr;
class PlatformAuditService{private const SENSITIVE=['password','password_confirmation','current_password','token','raw_token','reset_token','invitation_token','remember_token','secret','api_key'];public function record(string $action,?User $actor=null,?Model $auditable=null,array $metadata=[],?Request $request=null):PlatformAuditLog{return PlatformAuditLog::create(['actor_user_id'=>$actor?->id,'action'=>$action,'auditable_type'=>$auditable?->getMorphClass(),'auditable_id'=>$auditable?->getKey(),'ip_address'=>$request?->ip(),'user_agent'=>$request?->userAgent(),'request_id'=>$request?->attributes->get('request_id'),'metadata'=>$this->redact($metadata),'created_at'=>now()]);}public function redact(array $data):array{return collect($data)->mapWithKeys(function($v,$k){if(in_array(strtolower((string)$k),self::SENSITIVE,true)){return [$k=>'[REDACTED]'];}return [$k=>is_array($v)?$this->redact($v):$v];})->all();}}
